def register(add):
    """Use the already established validated Workbook schema and HTML renderer."""
    for raw in RECORDS.strip().splitlines():
        fields = raw.split('|')
        if len(fields) != 13:
            raise ValueError(f'invalid r53 workbook record ({len(fields)} fields): {fields[0]}')
        name, title, intro, a, b, c, l1, d1, l2, d2, l3, d3, limit = fields
        # Three topic checkpoints: the first two use authored descriptions;
        # the final checkpoint pairs the site-specific third procedure with its caveat.
        # The visible table is a concise index, not a reprint of the procedure.
        comparisons = ((l1, d1), (l2, d2), (l3, d3))
        # Retain the existing validation of meaningful paragraph lengths.
        add(name, title, intro, (a, b, c), comparisons, limit)


